-- User-authorised Hatchium embed. No lead export or forwarding is configured.
-- Existing page revision triggers retain the previous policy copy.
update public.pages set body_html = replace(body_html, '<p>Our public website does not use advertising cookies. Staff sign-in uses essential cookies only.</p>', '<p>Staff sign-in uses essential cookies. The public website also embeds a third-party chat service, described below. Browser storage used by that service depends on the provider and its configuration.</p>') || E'\n' || '<h2 id="website-chat">Website chat</h2><p>The website chat feature loads a third-party script from app.hatchium.ai, provided by Hatchium. Messages and contact details you enter in chat are handled by Hatchium to provide the conversation service. Ask the college if you have questions about how your chat data is handled.</p><p>Website enquiry forms are stored in the college CMS. Automatic forwarding of those forms to Make or the chat service is not currently enabled. We do not automatically copy website form fields into chat.</p>'
where slug='privacy-policy' and locale='en' and deleted_at is null
and position('id="website-chat"' in body_html)=0;
